import{createStudy,canvasSurface,seededRandom,clamp,lerp,downloadCanvas}from'./core.js';
const study=createStudy({id:20,title:'Quiet Storm',category:'Particles / Content / Scale',accent:'#e498ed',background:'#10101d',foreground:'#eeedf8'}),canvas=document.querySelector('#storm-canvas'),surface=canvasSurface(canvas),mask=document.createElement('canvas'),mctx=mask.getContext('2d',{willReadFrequently:true}),word=document.querySelector('#storm-word'),scale=document.querySelector('#storm-scale');
const random=seededRandom(20),particles=Array.from({length:1100},()=>({u:random(),v:random(),z:random(),angle:random()*Math.PI*2,radial:Math.sqrt(random()),radius:.6+random()*1.4,tx:0,ty:0}));let pointer={x:0,y:0,tx:0,ty:0},scroll=0,hold=false,clear=true,maskTimer=0;
function sampleText(){mask.width=760;mask.height=320;mctx.clearRect(0,0,760,320);const text=(word.value.trim()||'ELECTRIC').toUpperCase();canvas.setAttribute('aria-label','1100 luminous particles gathering into '+text+' and dissolving into a cloud');let font=150;mctx.font=`700 ${font}px Display`;while(mctx.measureText(text).width>700&&font>36){font-=3;mctx.font=`700 ${font}px Display`}mctx.fillStyle='#fff';mctx.textAlign='center';mctx.textBaseline='middle';mctx.fillText(text,380,166);const data=mctx.getImageData(0,0,760,320).data,points=[];for(let y=0;y<320;y+=3)for(let x=0;x<760;x+=3)if(data[(y*760+x)*4+3]>90)points.push({x:(x-380)/760,y:(y-160)/760});const seeded=seededRandom(420);for(const p of particles){const target=points[Math.floor(seeded()*points.length)]||{x:0,y:0};p.tx=target.x;p.ty=target.y}clear=true;study.invalidate()}
function draw({dt,time}){const{ctx,width:w,height:h}=surface;const k=dt?1-Math.exp(-dt*5):study.running()?0:1;pointer.x=lerp(pointer.x,pointer.tx,k);pointer.y=lerp(pointer.y,pointer.ty,k);ctx.fillStyle=clear||!dt?'#10101d':'rgba(16,16,29,.18)';ctx.fillRect(0,0,w,h);clear=false;const cx=w*.59,cy=h*.49,span=Math.min(w*.9,h*1.12),distance=(+scale.value/100)*(1+scroll*.65),gather=hold?1:Math.pow((Math.sin(time*.36-1)+1)/2,1.8),rotation=time*.045;const grad=ctx.createRadialGradient(cx,cy,0,cx,cy,span*.48);grad.addColorStop(0,'rgba(132,78,168,.075)');grad.addColorStop(1,'rgba(70,50,110,0)');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);for(const p of particles){const a=p.angle+rotation*(.35+p.z),r=p.radial*span*.44*distance;const cloudX=Math.cos(a)*r,cloudY=Math.sin(a)*r*(.38+p.z*.23)+Math.sin(a*3+time*.16)*span*.03;const textX=p.tx*span*1.3,textY=p.ty*span*1.3;const x=cx+lerp(cloudX,textX,gather)+pointer.x*(12+p.z*55),y=cy+lerp(cloudY,textY,gather)+pointer.y*(8+p.z*33);const alpha=.25+p.z*.65;ctx.fillStyle=p.z>.7?`rgba(244,218,253,${alpha})`:p.z>.36?`rgba(218,143,230,${alpha})`:`rgba(123,117,219,${alpha})`;ctx.beginPath();ctx.arc(x,y,p.radius*(.7+p.z*.7)*Math.min(1.6,distance),0,Math.PI*2);ctx.fill()}document.querySelector('#storm-state').textContent=hold?'HOLDING / '+(word.value.trim()||'ELECTRIC').toUpperCase():gather>.65?'GATHERING / A WORD BECOMES A WORLD':'DISSOLVING / A WORLD BECOMES A WORD'}
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();if(study.running()){pointer.tx=((e.clientX-r.left)/r.width-.5)*2;pointer.ty=((e.clientY-r.top)/r.height-.5)*2}study.invalidate()});canvas.addEventListener('pointerleave',()=>{pointer.tx=pointer.ty=0;study.invalidate()});word.addEventListener('input',()=>{clearTimeout(maskTimer);maskTimer=setTimeout(sampleText,90)});scale.addEventListener('input',()=>{clear=true;study.invalidate()});document.querySelector('#storm-form').addEventListener('click',e=>{hold=!hold;e.currentTarget.setAttribute('aria-pressed',String(hold));e.currentTarget.textContent=hold?'Release the word':'Hold the word';clear=true;study.invalidate()});function measure(){if(study.running())scroll=clamp((72-document.querySelector('.storm-scroll').getBoundingClientRect().top)/Math.max(1,document.querySelector('.storm-scroll').offsetHeight-document.querySelector('.storm-world').offsetHeight));clear=true;study.invalidate()}window.addEventListener('scroll',measure,{passive:true});study.onFrame(draw);study.onResize(()=>{surface.resize();measure();clear=true});sampleText();document.fonts.ready.then(sampleText);study.onMotion(run=>{clear=true;if(run)measure()});study.setReset(()=>{word.value='ELECTRIC';scale.value=85;hold=false;pointer={x:0,y:0,tx:0,ty:0};scroll=0;document.querySelector('#storm-form').textContent='Hold the word';document.querySelector('#storm-form').setAttribute('aria-pressed','false');sampleText();window.scrollTo({top:0,behavior:'auto'})});study.setExport(()=>downloadCanvas(canvas,'sub-quiet-storm.png'));study.cleanup(()=>{surface.dispose();clearTimeout(maskTimer);window.removeEventListener('scroll',measure)});
